-- Dumping data for table tokobajurafinakal.products: ~0 rows (approximately)
INSERT INTO `products` (`product_id`, `product_name`, `price`, `product_image`, `current_stock`, `product_desc`) VALUES
	(1, 'Kemeja Falnnel Pria', 150000.00, _binary , 25, 'Kemeja Flannel Pria Lengan Panjang Motif Kotak. \nLengkapi gaya harianmu dengan Kemeja Flannel.\nDibuat dari bahan katun flannel pilihan yang lembut di kulit, hangat, tapi tetap adem saat dipakai seharian.  \nDesain motif kotak-kotaknya timeless dan gampang dipadukan. Cocok dipakai kancing penuh untuk tampilan rapi, atau dibuka sebagai outer di atas kaus polos untuk gaya kasual yang santai'),
	(2, 'Kaos Hitam O-neck', 85000.00, _binary , 45, 'Kaos Polos Hitam O-Neck Lengan Pendek (Unisex)   Item wajib yang harus ada di lemari pakaianmu! Kaos Hitam O-Neck hadir dengan warna hitam pekat yang elegan, anti-menerawang, dan super gampang dipadukan dengan celana jeans, chino, maupun outer favoritmu.Terbuat dari 100% Cotton Combed yang lembut di kulit dan cepat menyerap keringat, kaos ini tetap terasa sejuk meski dipakai beraktivitas seharian di cuaca panas'),
	(3, 'Celana Jeans Denim', 100000.00, _binary , 67, 'Celana jeans denim yang dirancang untuk menemani setiap langkah dan aktivitas harianmu dengan nyaman. Potongannya jatuh pas di kaki dan terasa leluasa saat dipakai bergerak, sehingga tetap enak dikenakan dari pagi hingga malam. Dengan tampilan klasik yang tak lekang oleh waktu, celana ini sangat mudah dipadukan dengan kaus polos favorit untuk gaya santai maupun kemeja saat ingin terlihat lebih rapi.'),
	(4, 'Jaket Hoodie Navi', 125000.00, _binary , 37, 'Kehangatan dan kenyamanan yang pas untuk menemani rutinitas harianmu. Hoodie klasik berwarna navy ini hadir dengan potongan yang rileks dan terasa lembut di kulit, membuatmu tetap nyaman baik saat cuaca sedang sejuk maupun beraktivitas di ruangan ber-AC. Warna birunya yang dalam memberikan kesan tenang sekaligus mudah dipadukan dengan celana jeans atau kaus favorit untuk tampilan santai yang selalu siap diandalkan.'),
	(5, 'Sweater Rajut Wanita', 250000.00, _binary , 87, 'Kehangatan dan kenyamanan yang pas untuk menemani rutinitas harianmu. Hoodie klasik berwarna navy ini hadir dengan potongan yang rileks dan terasa lembut di kulit, membuatmu tetap nyaman baik saat cuaca sedang sejuk maupun beraktivitas di ruangan ber-AC. Warna birunya yang dalam memberikan kesan tenang sekaligus mudah dipadukan dengan celana jeans atau kaus favorit untuk tampilan santai yang selalu siap diandalkan.');
INSERT INTO `products` (`product_id`, `product_name`, `price`, `product_image`, `current_stock`, `product_desc`) VALUES
	(6, 'Batik Hitam Elegan', 175000.00, _binary , 28, 'Pancarkan pesona yang berwibawa dan anggun lewat balutan batik hitam elegan ini. Perpaduan warna hitam yang dalam dengan motif batik yang memikat menghadirkan kesan mewah tanpa terasa berlebihan. Potongannya dirancang rapi dan nyaman dikenakan sepanjang acara, menjadikannya pilihan sempurna untuk menghadiri undangan resmi, jamuan makan malam, hingga momen istimewa lainnya.'),
	(7, 'Kaos Hanley', 135000.00, _binary , 78, 'Hadirkan kesan santai yang tetap terlihat rapi lewat kaos Henley berpotongan bersih ini. Detail bukaan kancing di bagian dada memberikan sentuhan maskulin yang berkarakter, membuatnya tampak lebih dewasa dibandingkan kaos polos biasa tanpa kehilangan rasa nyamannya. Bahannya terasa lembut dan sejuk di kulit sepanjang hari, sehingga sangat pas dikenakan sendiri untuk gaya harian maupun dipadukan dengan jaket favoritmu.'),
	(8, 'Kaos Raglan', 95000.00, _binary , 45, 'Tampil lebih dinamis dan penuh energi dengan kaos Raglan berpotongan lengan klasik ini. Perpaduan dua warna kontras pada bagian badan dan lengan menghadirkan siluet sporty yang segar serta memberi keleluasaan ekstra saat bahu bergerak. Nyaman dikenakan untuk menemani aktivitas padat di luar ruangan, pergi ke kampus, maupun sekadar bersantai bersama teman di akhir pekan.'),
	(9, 'Tanktop', 75000.00, _binary , 135, 'Teman setia untuk kenyamanan maksimal di hari-hari yang hangat maupun saat beraktivitas aktif. Tank top ini dirancang dengan potongan yang mengikuti lekuk tubuh secara alami dan terasa ringan di kulit, memberikan ruang gerak bebas tanpa rasa gerah. Sangat praktis dikenakan untuk berolahraga ringan, bersantai di rumah, hingga dijadikan dalaman kemeja atau jaket agar penampilan tetap rapi'),
	(10, 'Jaket Corduroy', 535000.00, _binary , 32, 'Tambahkan sentuhan vintage yang hangat dan berkarakter pada penampilanmu lewat jaket corduroy ini. Permukaannya yang bertekstur halus menghadirkan nuansa klasik yang langsung membuat padu padan pakaian sederhana terlihat lebih hidup dan berkelas. Potongannya nyaman dilapiskan di atas kaos polos maupun kemeja favorit, menjadikannya luaran andalan untuk menemani perjalanan sore hingga suasana santai di malam hari.'),
	(11, 'Cangcut Gusion', 99999999.00, _binary , 11, 'Tunjukkan totalitasmu sebagai user Gusion dari pagi sampai malam lewat celana dalam bermotif karakter ikonik ini. Hadir dengan cetakan gambar Gusion yang tajam dan hidup, pakaian dalam ini dirancang khusus untuk memberikan kenyamanan ekstra saat kamu beraktivitas maupun fokus push rank berjam-jam. Bahannya terasa lembut, sejuk di kulit, dan mengikuti gerak tubuh dengan leluasa tanpa terasa menekan di pinggang.');

